inline void testVulkanBufferCopyCandidate(HMODULE library,Handle device,Handle queue,uint32_t family,uint64_t source,const void*expected,size_t bytes,const VkProbeMemoryProperties&properties){
 static_assert(sizeof(VkProbePoolInfo)==24&&sizeof(VkProbeCommandAllocation)==32&&sizeof(VkProbeCommandBegin)==32&&sizeof(VkProbeSubmit)==72&&sizeof(VkProbeMemoryBarrier)==24,"Vulkan command ABI");
 auto create=load<VkProbeCreateBuffer>(library,"vkCreateBuffer");auto destroy=load<VkProbeDestroyBuffer>(library,"vkDestroyBuffer");auto requirements=load<VkProbeGetRequirements>(library,"vkGetBufferMemoryRequirements");auto allocate=load<VkProbeAllocateMemory>(library,"vkAllocateMemory");auto free=load<VkProbeFreeMemory>(library,"vkFreeMemory");auto bind=load<VkProbeBindMemory>(library,"vkBindBufferMemory");auto map=load<VkProbeMapMemory>(library,"vkMapMemory");auto unmap=load<VkProbeUnmapMemory>(library,"vkUnmapMemory");auto createPool=load<VkProbeCreatePool>(library,"vkCreateCommandPool");auto destroyPool=load<VkProbeDestroyPool>(library,"vkDestroyCommandPool");auto commands=load<VkProbeAllocateCommands>(library,"vkAllocateCommandBuffers");auto begin=load<VkProbeBeginCommand>(library,"vkBeginCommandBuffer");auto end=load<VkProbeEndCommand>(library,"vkEndCommandBuffer");auto copy=load<VkProbeCopyBuffer>(library,"vkCmdCopyBuffer");auto barrier=load<VkProbePipelineBarrier>(library,"vkCmdPipelineBarrier");auto submit=load<VkProbeQueueSubmit>(library,"vkQueueSubmit");auto idle=load<VkProbeQueueIdle>(library,"vkQueueWaitIdle");
 auto check=[](int32_t result){if(result)throw std::runtime_error("Vulkan copy result "+std::to_string(result));};uint64_t destination=0,memory=0,pool=0;bool submitted=false;try{
  VkProbeBufferInfo info{};info.type=12;info.size=bytes;info.usage=2;check(create(device,&info,nullptr,&destination));VkProbeMemoryRequirements req{};requirements(device,destination,&req);uint32_t type=32;for(uint32_t n=0;n<properties.typeCount;++n)if((req.bits&(uint32_t(1)<<n))&&(properties.types[n].flags&6)==6){type=n;break;}if(type==32)throw std::runtime_error("readback memory unavailable");VkProbeMemoryAllocateInfo allocation{};allocation.type=5;allocation.size=req.size;allocation.memoryType=type;check(allocate(device,&allocation,nullptr,&memory));check(bind(device,destination,memory,0));void*mapped=nullptr;check(map(device,memory,0,bytes,0,&mapped));std::memset(mapped,0xa5,bytes);unmap(device,memory);
  VkProbePoolInfo poolInfo{};poolInfo.type=39;poolInfo.family=family;check(createPool(device,&poolInfo,nullptr,&pool));VkProbeCommandAllocation commandAllocation{};commandAllocation.type=40;commandAllocation.pool=pool;commandAllocation.count=1;Handle command=nullptr;check(commands(device,&commandAllocation,&command));VkProbeCommandBegin beginInfo{};beginInfo.type=42;beginInfo.flags=1;check(begin(command,&beginInfo));VkProbeCopyRegion region{0,0,bytes};copy(command,source,destination,1,&region);VkProbeMemoryBarrier memoryBarrier{};memoryBarrier.type=46;memoryBarrier.source=0x1000;memoryBarrier.destination=0x2000;barrier(command,0x1000,0x4000,0,1,&memoryBarrier,0,nullptr,0,nullptr);check(end(command));VkProbeSubmit submission{};submission.type=4;submission.commandCount=1;submission.commands=&command;check(submit(queue,1,&submission,0));submitted=true;check(idle(queue));submitted=false;
  check(map(device,memory,0,bytes,0,&mapped));bool equal=std::memcmp(mapped,expected,bytes)==0;unmap(device,memory);if(!equal)throw std::runtime_error("GPU copy readback mismatch");std::cout<<"gpu_copy_bytes="<<bytes<<" readback_exact=1\n";destroyPool(device,pool,nullptr);pool=0;destroy(device,destination,nullptr);destination=0;free(device,memory,nullptr);memory=0;
 }catch(...){if(submitted)idle(queue);if(pool)destroyPool(device,pool,nullptr);if(destination)destroy(device,destination,nullptr);if(memory)free(device,memory,nullptr);throw;}
}
